package com.project.entity.enterprise;
import com.project.entity.Employee; import javax.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="payroll_records", uniqueConstraints=@UniqueConstraint(columnNames={"employee_id","payroll_month","payroll_year"}))
public class PayrollRecord { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="employee_id",nullable=false) private Employee employee; @Column(name="payroll_month", nullable=false) private int payrollMonth; @Column(name="payroll_year", nullable=false) private int payrollYear; @Column(precision=12,scale=2) private BigDecimal gross; @Column(precision=12,scale=2) private BigDecimal deductions; @Column(precision=12,scale=2) private BigDecimal net; private String status="PROCESSED"; private LocalDateTime processedAt=LocalDateTime.now(); public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public int getPayrollMonth(){return payrollMonth;} public void setPayrollMonth(int v){payrollMonth=v;} public int getPayrollYear(){return payrollYear;} public void setPayrollYear(int v){payrollYear=v;} public BigDecimal getGross(){return gross;} public void setGross(BigDecimal v){gross=v;} public BigDecimal getDeductions(){return deductions;} public void setDeductions(BigDecimal v){deductions=v;} public BigDecimal getNet(){return net;} public void setNet(BigDecimal v){net=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getProcessedAt(){return processedAt;} public void setProcessedAt(LocalDateTime v){processedAt=v;} }
